insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g5_tech_v1'
from (values
('126.10.c.4',4,'Predicting that self-driving buses could change how a town gets to school is thinking about how emerging technologies may impact...','["communities", "clouds", "pencils", "rocks"]'::jsonb,0,'Predict technology''s effects.','original'),
('126.10.c.4',4,'Which is the best prediction about robots that help in hospitals?','["they will stop all doctors from working", "they may help workers care for more patients", "they will turn into plants", "they will make hospitals disappear"]'::jsonb,1,'Predictions are reasonable.','original'),
('126.10.c.6',4,'You use a spreadsheet to average the quiz scores of your class and decide whether the class improved. You are using digital tools to analyze data and make an...','["escape", "error", "inference", "echo"]'::jsonb,2,'Analyze to make inferences.','original'),
('126.10.c.6',4,'Sorting a spreadsheet from highest to lowest sales is a way to...','["lose data", "hide data", "erase data", "transform data"]'::jsonb,3,'Sorting transforms data.','original'),
('126.10.c.7',4,'A line graph is the best visualization for showing how something changes over...','["time", "a desk", "a door", "a lunch"]'::jsonb,0,'Line graphs show change over time.','original'),
('126.10.c.7',4,'To show how a class''s favorite fruits compare, which visualization is most appropriate?','["a timeline", "a bar graph", "a calendar", "a map"]'::jsonb,1,'Bar graphs compare categories.','original'),
('126.10.c.1.A',4,'A graphic organizer that shows a big problem branching into smaller parts is a...','["ruler", "recipe", "concept map", "calendar"]'::jsonb,2,'Concept maps decompose problems.','original'),
('126.10.c.1.B',4,'Every time your phone battery drops below 20 percent, it warns you at the same point. From this pattern you can predict that it will...','["never warn again", "blow up", "change colors", "warn you again at 20 percent"]'::jsonb,3,'Patterns support predictions.','original'),
('126.10.c.1.C',4,'An outline that lists the problem, ideas for solutions and a timeline for building the program is a...','["collaborative outline", "menu", "song", "joke"]'::jsonb,0,'Outlines plan projects.','original'),
('126.10.c.1.D',4,'Two programs both draw a square. One uses 20 blocks and one uses 5 blocks with a loop. The better algorithm is usually the one that is...','["longer and messier", "shorter and efficient", "louder", "slower"]'::jsonb,1,'Compare algorithms for efficiency.','original'),
('126.10.c.2.A',4,'In a game, a variable called ''timer'' starts at 60 and goes down by 1 each second. The variable is being used to store and...','["play music", "erase data", "modify data", "draw boxes"]'::jsonb,2,'Variables store and change values.','original'),
('126.10.c.2.B',4,'In block-based coding, a block that starts the program when you click the green flag is an...','["variable", "loop", "comment", "event"]'::jsonb,3,'Events trigger actions.','original'),
('126.10.c.2.B',4,'A block-based program that moves a sprite, repeats the move 5 times and checks if it touches an edge uses sequences, loops and...','["conditionals", "dancing", "noise", "spelling"]'::jsonb,0,'Programs combine blocks.','original'),
('126.10.c.2.C',4,'Copying part of a working program to use in a new game, after studying how it works, is reusing...','["paint", "code", "chalk", "paper"]'::jsonb,1,'Code can be reused.','original'),
('126.10.c.3.A',4,'Not giving up when your first design fails is called...','["sleeping", "forgetting", "persistence", "hiding"]'::jsonb,2,'Persistence helps design.','original'),
('126.10.c.3.B',4,'Brainstorming several different ideas for solving a problem before choosing one is generating multiple...','["errors", "erasers", "echoes", "solutions"]'::jsonb,3,'Design generates options.','original'),
('126.10.c.5.A',4,'The number of minutes of daily exercise is quantitative data. A student''s description of how they feel after exercise is...','["qualitative data", "quantitative data", "numbers only", "measurements"]'::jsonb,0,'Descriptions are qualitative.','original'),
('126.10.c.5.B',4,'In a search, the word AND between two keywords tells the engine to find pages with...','["neither word", "both words", "only one word", "no words"]'::jsonb,1,'Boolean AND needs both.','original'),
('126.10.c.5.B',4,'The Boolean word OR in a search finds pages that contain...','["both keywords only", "neither keyword", "either keyword", "only pictures"]'::jsonb,2,'OR broadens a search.','original'),
('126.10.c.5.B',4,'Choosing to search only for pages updated in the last year is using a...','["loophole", "ladder", "label", "limiter"]'::jsonb,3,'Limiters narrow results.','original'),
('126.10.c.8.A',3,'Which is part of your digital footprint?','["your game history and social media posts", "your lunch", "your height", "the color of your shirt"]'::jsonb,0,'Online activity creates a footprint.','original'),
('126.10.c.8.B',3,'When writing to a teacher, a respectful digital approach is to use...','["emojis only", "complete sentences and a polite tone", "all capital letters", "slang only"]'::jsonb,1,'Match tone to audience.','original'),
('126.10.c.8.C',4,'When collaborating with peers in a shared document, appropriate etiquette is to...','["delete their work", "type over them", "respect others'' edits and add comments politely", "ignore the plan"]'::jsonb,2,'Collaborate respectfully.','original'),
('126.10.c.9.A',4,'Following the school''s AUP shows that you understand why responsible and ethical use matters. This is an example of...','["ignoring the school", "careless play", "rule avoidance", "ethical technology use"]'::jsonb,3,'Follow AUP.','original'),
('126.10.c.9.B',4,'Copyright law exists to protect the creators of original work. Using a song or picture without permission can lead to...','["legal and school consequences", "extra recess", "no results", "free prizes"]'::jsonb,0,'Consequences exist.','original'),
('126.10.c.9.C',4,'A citation for a picture should include the creator, title and where you found it, such as the...','["shoe size", "website address", "lunch", "weather"]'::jsonb,1,'Citations track sources.','original'),
('126.10.c.10.A',4,'Using a secured internet connection, like a password-protected network, helps protect your...','["lunch", "shoes", "digital information", "desk"]'::jsonb,2,'Secure connections help.','original'),
('126.10.c.10.B',4,'Websites that use tracking technology to follow where you click are collecting data about your online...','["shoes", "lunch", "sleep", "navigation"]'::jsonb,3,'Tracking follows navigation.','original'),
('126.10.c.10.B',4,'A good strategy for protecting privacy online is to...','["review and limit the data apps can collect", "click all pop-ups", "share everything", "use one weak password everywhere"]'::jsonb,0,'Control your privacy settings.','original'),
('126.10.c.10.C',4,'An online argument can escalate quickly. A good way to stand up to cyberbullying is to...','["join the bullying", "support the target and report to a trusted adult", "share the messages publicly", "laugh at it"]'::jsonb,1,'Advocate for self and others.','original'),
('126.10.c.11.A',4,'A file ending in .docx or .txt is usually a...','["graphic file", "video file", "text file", "sound file"]'::jsonb,2,'Text file types.','original'),
('126.10.c.11.A',4,'A file ending in .png or .jpg is usually a...','["program", "text file", "spreadsheet", "graphic file"]'::jsonb,3,'Graphics file types.','original'),
('126.10.c.11.A',4,'A file ending in .mp4 is usually a...','["multimedia file", "text file", "graphic file only", "spreadsheet"]'::jsonb,0,'Multimedia includes video.','original'),
('126.10.c.11.B',3,'To change the look of text, such as making it bold or a different size, you use...','["the printer ink", "formatting tools", "the volume", "the power cord"]'::jsonb,1,'Formatting changes appearance.','original'),
('126.10.c.12.A',4,'Short-range wireless technology such as Bluetooth is used to connect devices that are...','["across the ocean", "underwater only", "close together", "on different planets"]'::jsonb,2,'Bluetooth is short range.','original'),
('126.10.c.12.A',4,'The software that manages a computer''s hardware and runs other programs is the...','["screen", "printer", "keyboard", "operating system"]'::jsonb,3,'The OS manages the computer.','original'),
('126.10.c.12.B',4,'A folder named ''5th Science > Ecosystems > Food Webs'' shows an organized folder...','["structure", "puzzle", "mistake", "joke"]'::jsonb,0,'Folders nest.','original'),
('126.10.c.12.C',3,'Practicing touch keyboarding to type faster with fewer mistakes improves speed and...','["weight", "accuracy", "volume", "height"]'::jsonb,1,'Accuracy matters.','original'),
('126.10.c.12.D',4,'The keyboard shortcut to undo the last action on many computers is...','["Control and Q", "Shift and Tab", "Control (or Command) and Z", "Alt and Space"]'::jsonb,2,'Ctrl+Z undoes.','original'),
('126.10.c.12.D',4,'The shortcut Control (or Command) and S usually...','["deletes your work", "closes your work", "prints your work", "saves your work"]'::jsonb,3,'S saves.','original'),
('126.10.c.12.E',4,'If you do not know how to make a table in a document, a good first step is to use the program''s...','["help feature or tutorial", "printer", "nearest trash can", "power button"]'::jsonb,0,'Help sources teach features.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Technology Applications' and d.language = 'en'
on conflict (fingerprint) do nothing;
